// HBM-FORM-SPLIT d44v part 29: issue tile of ot_hgi_coll_gq_issue, GENERATED by mk_gq.py from the kit RTL; quantisers moved out, see ot_hgi_gq_aq_tile.sv.
`timescale 1ns/1ps
`default_nettype none
module ot_hgi_coll_gqi_issue #(
    parameter integer MUT = 0,      // bench mutants: 1 rx src of h=1 uses the CW table on CCW, 2 exponent bias 126,
                                    // 3 publish lands at i+1, 4 self-land skipped, 5 ring-B command one edge late
    parameter integer VM_RT = 0
)(
    input  wire          clk, rst_n,
    input  wire [1:0]    qid,
    input  wire [7:0]    tgt,
    // F20 host frame
    input  wire          cfg_v,
    input  wire [7:0]    cfg_target,
    input  wire [11:0]   cfg_addr,
    input  wire [255:0]  cfg_data,
    input  wire          desc_v,
    input  wire [11:0]   desc_base,
    input  wire [12:0]   desc_limit,
    input  wire [15:0]   desc_loops,
    input  wire          launch_v,
    output wire          configured, tgt_fault,
    output reg           active, done,
    output reg           fault,
    // ISA ring-A fields from the COLL issuer (v5 p_ring[57:0] order) + its lp data
    input  wire [57:0]   isa_ring,
    input  wire [255:0]  isa_lp_data,
    // ring A (ot_hgi_coll_ring_ag) command ports, merged
    output reg           ra_lp_we,
    output reg  [2:0]    ra_lp_tag,
    output reg  [255:0]  ra_lp_data,
    output reg           ra_state_read_add, ra_state_read_tx, ra_state_read_rr,
    output reg  [2:0]    ra_state_add_tag, ra_state_tx_tag, ra_state_rr_tag,
    output reg  [1:0]    ra_state_add_src,
    output reg           ra_state_add_rhs_acc, ra_state_tx_acc,
    output reg           ra_add_v,
    output reg  [2:0]    ra_add_tag,
    output reg  [1:0]    ra_add_src,
    output reg           ra_add_rhs_acc,
    output reg  [1:0]    ra_tx_inject, ra_tx_forward,
    output reg  [2:0]    ra_tx_tag,
    output reg  [1:0]    ra_tx_dst,
    output reg           ra_tx_result, ra_tx_acc, ra_tx_gather,
    output reg  [3:0]    ra_tx_ttl,
    output reg  [1:0]    ra_rx_slot,
    output reg  [3:0]    ra_rx_kind, ra_rx_src,
    output reg  [5:0]    ra_rx_tag,
    output reg           ra_rr_local,
    output reg  [2:0]    ra_rr_local_tag,
    // ring B (ot_hgi_coll_ring_b_stop) command ports
    output reg           rb_lp_we,
    output reg  [2:0]    rb_lp_tag,
    output reg  [255:0]  rb_lp_data,
    output reg           rb_state_read_tx,
    output reg  [2:0]    rb_state_tx_tag,
    output reg  [1:0]    rb_tx_inject, rb_tx_forward,
    output reg  [2:0]    rb_tx_tag,
    output reg  [3:0]    rb_tx_ttl,
    output reg  [1:0]    rb_rx_slot,
    output reg  [3:0]    rb_rx_kind, rb_rx_src,
    output reg  [5:0]    rb_rx_tag,
    // quadrant VM read group (via the COLL read share); banks 0-3 / 4-7 on separate faces
    output wire [67:0]   vm_rq_lo, vm_rq_hi,
    input  wire [1027:0] vm_rr_lo, vm_rr_hi,
    // to the landing leaf: descriptor at fire, event stream (stage 0), payload P (stage 24)
    output reg           ld_fire,
    output reg  [52:0]   ld_desc,      // {r2, self, qbg, F[9:0], Bs[7:0], dst[15:0], stride[15:0]}
    output wire          ld_ev_v,
    output wire [9:0]    ld_ev_k,
    output wire [1:0]    ld_p_v,
    output wire [511:0]  ld_p_d,
    // quantiser tiles: next-state of the former aq_v / aq_x, faces of the two tiles replace the capture stages
    output wire          aq0_v, aq1_v,
    output wire [1023:0] aq0_x, aq1_x,
    input  wire          aq0_vo, aq1_vo, aq0_fault, aq1_fault,
    input  wire [255:0]  aq0_q, aq1_q,
    input  wire [9:0]    aq0_e, aq1_e
);
    localparam integer V = VM_RT;
    localparam integer ND = 40 + V;                  // event pipeline depth (last use: ev[36+V])
    localparam integer S_QR = 0, S_PR = 15, S_QCAP = 8 + V, S_PCAP = 23 + V, S_P = 24 + V;
    localparam integer S_BLP = 24 + V, S_BRD = 25 + V, S_BINJ = 27 + V, S_BRX = 27 + V;   // + 2h
    // ------------------------------------------------------------------ reset relay (3 edges) + straps
    wire [0:0] rl;
    ot_rst_relay #(.REGIONS(1)) u_rst(.clk(clk), .rst_n_in(rst_n), .rst_n(rl));
    wire rn = rl[0];
    wire [1:0] aq_vo_q = {aq1_vo, aq0_vo}, aq_fault_q = {aq1_fault, aq0_fault}; reg flt_q; wire flt_n = flt_q;
    reg [135:0] vm_rq; wire [2055:0] vm_rr = {vm_rr_hi, vm_rr_lo};
    assign vm_rq_lo = vm_rq[67:0]; assign vm_rq_hi = vm_rq[135:68];
    reg [1:0] aq_v; reg [2047:0] aq_x;
    assign {aq1_v, aq0_v} = aq_v; assign {aq1_x, aq0_x} = aq_x;
    reg [1:0] q_id;
    always @(posedge clk) q_id <= qid;
    function automatic [1:0] nextq(input [1:0] q); case (q) 2'd0: nextq = 2'd1; 2'd1: nextq = 2'd3; 2'd3: nextq = 2'd2; default: nextq = 2'd0; endcase endfunction
    function automatic [1:0] prevq(input [1:0] q); case (q) 2'd0: prevq = 2'd2; 2'd1: prevq = 2'd0; 2'd3: prevq = 2'd1; default: prevq = 2'd3; endcase endfunction
    // arrival source of hop h on direction d at this stop
    function automatic [1:0] srcq(input [1:0] q, input integer d, input integer h);
        reg [1:0] s; s = q;
        for (integer j = 0; j < h; j = j + 1) begin
            if (d == 0 || (MUT == 1 && h == 1)) s = prevq(s); else s = nextq(s);
        end
        srcq = s;
    endfunction
    // ------------------------------------------------------------------ F20 target + descriptor rows
    wire p_we, p_sv; wire [7:0] p_wa, p_sb; wire [255:0] p_wd; wire [8:0] p_sl; wire [15:0] p_lp;
    ot_static_program_target #(.TARGET(8'hff), .PCW(8), .TGT_PIN(1), .CAP_CLK(0)) u_target(
        .clk(clk), .clk_cap(clk), .rst_n(rst_n), .tgt(tgt), .cfg_v(cfg_v), .cfg_target(cfg_target), .cfg_addr(cfg_addr),
        .cfg_data(cfg_data), .desc_v(desc_v), .desc_base(desc_base), .desc_limit(desc_limit), .desc_loops(desc_loops),
        .launch_v(launch_v), .program_active(active), .program_cfg_we(p_we), .program_cfg_addr(p_wa),
        .program_cfg_data(p_wd), .program_start_v(p_sv), .program_start_base(p_sb), .program_start_limit(p_sl),
        .program_start_loops(p_lp), .configured(configured), .fault(tgt_fault));
    localparam integer DW = 101;
    reg [DW-1:0] rf [0:15];
    always @(posedge clk) if (p_we && p_wa < 8'd16) rf[p_wa[3:0]] <= p_wd[DW-1:0];
    // ------------------------------------------------------------------ calendar
    reg run; reg [3:0] cur, b0; reg [4:0] lim; reg [15:0] tl, per, lps;
    // HBM-HARD-1-GQ 11-07, PIN CYCLE +1 (vD routed: cur fans out to 129 loads for the 101-bit row mux, cur -> compare -> fire
    // arrives at 450 ps, then fire fans out to 64 enables; 37 endpoints -16 to -57): the calendar (cur, tl, lps, run) keeps its own
    // compare fire_c on a compare-only copy cur_t; everything downstream of the calendar runs from the REGISTERED fire and row,
    // so every output except configured / tgt_fault is exactly one edge later for inputs one edge later.
    (* keep *) reg [3:0] cur_t;
    wire fire_c = run && {1'b0, cur_t} < lim && tl == rf[cur_t][18:3];
    reg fire; reg [DW-1:0] rc;
    always @(posedge clk or negedge rn) if (!rn) fire <= 1'b0; else fire <= fire_c;
    always @(posedge clk) rc <= rf[cur];
    reg run_q, p_sv_q, ps_bad, row_miss;
    // gather state (held while busy)
    reg busy; reg g_qbg, g_r2, g_self; reg [9:0] g_f; reg [7:0] g_bs; reg [15:0] g_src, g_dst, g_str;
    reg [9:0] g_kn;                                   // ring indices K = ceil(F / R)
    reg iss; reg [9:0] ik; reg [1:0] iph; localparam integer DRW = $clog2(ND); reg [DRW-1:0] drain;   // 6 b at VM_RT 0 (as built)
    wire [9:0] f_kn = rc[1] ? 10'((rc[28:19] + 10'd1) >> 1) : rc[28:19];
    wire [7:0] f_es = 8'((rc[36:29] + 8'd31) >> 5);
    wire f_bad = rc[28:19] == 10'd0 || |rc[71:69] ||
                 (rc[0] && (rc[36:29] == 8'd0 || rc[36:29] > 8'd64 || {2'b0, rc[28:19]} != {2'b0, rc[36:29]} + {4'b0, f_es}));
    wire ev_in_v = iss && iph != 2'd2;
    always @(posedge clk or negedge rn) begin
        if (!rn) begin
            run <= 1'b0; busy <= 1'b0; iss <= 1'b0; fault <= 1'b0; active <= 1'b0; done <= 1'b0; drain <= '0;
            cur <= 4'd0; cur_t <= 4'd0; b0 <= 4'd0; lim <= 5'd0; tl <= 16'd0; per <= 16'd0; lps <= 16'd0; ik <= 10'd0; iph <= 2'd0;
            run_q <= 1'b0; p_sv_q <= 1'b0; ps_bad <= 1'b0; row_miss <= 1'b0;
        end else begin
            done <= 1'b0;
            run_q <= run; p_sv_q <= p_sv; row_miss <= 1'b0;
            ps_bad <= p_sl > 9'd16 || rf[p_sb[3:0]][100:85] == 16'd0;
            active <= run_q || busy || p_sv_q;
            if (active && !(run_q || busy || p_sv_q)) done <= 1'b1;
            if (p_sv_q && (run_q || busy || ps_bad)) fault <= 1'b1;
            if (row_miss) fault <= 1'b1;
            if (p_sv) begin
                run <= 1'b1; cur <= p_sb[3:0]; cur_t <= p_sb[3:0]; b0 <= p_sb[3:0]; lim <= p_sl[4:0]; tl <= 16'd0; lps <= p_lp;
                per <= rf[p_sb[3:0]][100:85];
            end else if (run) begin
                if (fire_c) begin cur <= cur + 4'd1; cur_t <= cur_t + 4'd1; end
                if (tl == per - 16'd1) begin
                    if (lps <= 16'd1) run <= 1'b0;
                    else begin lps <= lps - 16'd1; tl <= 16'd0; cur <= b0; cur_t <= b0; end
                    if ({1'b0, cur} + (fire_c ? 5'd1 : 5'd0) != lim) row_miss <= 1'b1;   // a row never fired this period
                end else tl <= tl + 16'd1;
            end
            if (fire) begin
                if (busy || f_bad) fault <= 1'b1;
                busy <= 1'b1; iss <= 1'b1; ik <= 10'd0; iph <= 2'd0;
            end else if (iss) begin
                if (ev_in_v) begin
                    ik <= ik + 10'd1;
                    if (ik == g_kn - 10'd1) begin iss <= 1'b0; drain <= DRW'(ND - 1); end
                end
                iph <= (iph == 2'd2) ? 2'd0 : iph + 2'd1;
            end else if (busy) begin
                if (drain == '0) busy <= 1'b0; else drain <= drain - 1'b1;
            end
            if (|(aq_fault_q & aq_vo_q)) fault <= 1'b1;
            if (flt_n) fault <= 1'b1;
        end
    end
    generate if (V == 0) begin : g_ld0
        always @(posedge clk or negedge rn) if (!rn) ld_fire <= 1'b0; else ld_fire <= fire;
        always @(posedge clk) ld_desc <= {rc[1], rc[2], rc[0], rc[28:19], rc[36:29], rc[68:53], rc[84:69]};
    end else begin : g_ldv
        // fire delayed V edges; the descriptor comes from the gather state loaded at fire (held: fires never overlap)
        reg [V-1:0] fd;
        always @(posedge clk or negedge rn)
            if (!rn) begin fd <= '0; ld_fire <= 1'b0; end
            else begin fd <= {fd, fire}; ld_fire <= fd[V-1]; end
        always @(posedge clk) ld_desc <= {g_r2, g_self, g_qbg, g_f, g_bs, g_dst, g_str};
    end endgenerate
    always @(posedge clk) if (fire) begin
        g_qbg <= rc[0]; g_r2 <= rc[1]; g_self <= rc[2]; g_f <= rc[28:19]; g_bs <= rc[36:29];
        g_src <= rc[52:37]; g_dst <= rc[68:53]; g_str <= rc[84:69]; g_kn <= f_kn;
    end
    // ------------------------------------------------------------------ event pipeline {v, k}
    reg [ND-1:0] ev_v; reg [9:0] ev_k [0:ND-1];
    always @(posedge clk or negedge rn)
        if (!rn) ev_v <= '0; else ev_v <= {ev_v[ND-2:0], ev_in_v};
    always @(posedge clk) begin
        ev_k[0] <= ik;
        for (integer s = 1; s < ND; s = s + 1) ev_k[s] <= ev_k[s-1];
    end
    // flit decode of an entry
    function automatic [10:0] flit_i(input [9:0] k, input integer r); flit_i = g_r2 ? {k, 1'(r)} : (r == 0 ? {1'b0, k} : 11'h7ff); endfunction
    function automatic fv(input [9:0] k, input integer r);     // flit (k, r) exists
        reg [10:0] i; i = flit_i(k, r); fv = (r == 0 || g_r2) && i < {1'b0, g_f};
    endfunction
    function automatic is_code(input [10:0] i); is_code = !g_qbg || i < {3'b0, g_bs}; endfunction
    function automatic [15:0] sec_add(input [15:0] s, input [12:0] a); sec_add = {s[15:13], s[12:0] + a}; endfunction
    // DIE-HBM-82-COLL vA 11-06 (routed vB2 TT -135 ps: 1.3k endpoints behind the bank-select / mode decode of g_src, g_r2,
    // ev_k fanning out to 2,560 bits of 8:1 read muxes): the aq_x and p_d bank selects, the p_d source mode and the
    // exponent-byte write enables are REGISTERED one edge early from the next state of the gather registers
    // (fire ? rc : g_*) and of the event pipeline (ev_k[s-1] -> ev_k[s], ev_v[s-1] -> ev_v[s], same reset); the 512-bit
    // clear of ex on fire becomes a 1-bit flag ex_z applied on read.  Exact retiming, 0 added cycles (lock-step bench
    // vs the unchanged original with mutants).
    wire [2:0] g_src_n3 = fire ? rc[39:37] : g_src[2:0];
    wire       g_r2_n   = fire ? rc[1] : g_r2;
    wire       g_qbg_n  = fire ? rc[0] : g_qbg;
    wire [9:0] g_f_n    = fire ? rc[28:19] : g_f;
    wire [7:0] g_bs_n   = fire ? rc[36:29] : g_bs;
    function automatic [10:0] flit_n(input [9:0] k, input integer r, input r2); flit_n = r2 ? {k, 1'(r)} : (r == 0 ? {1'b0, k} : 11'h7ff); endfunction
    function automatic fv_n(input [9:0] k, input integer r, input r2, input [9:0] f);
        reg [10:0] i; i = flit_n(k, r, r2); fv_n = (r == 0 || r2) && i < {1'b0, f};
    endfunction
    function automatic code_n(input [10:0] i, input qbg, input [7:0] bs); code_n = !qbg || i < {3'b0, bs}; endfunction
    // HBM-HARD-5 11-08 vLF2 (vLF routed TT -54.42/14: g_src -> 13-bit sec_add -> bank decode -> vm_rq): the VM read
    // addresses (13-bit low sums) and the request conditions are REGISTERED one edge early from the next state of the gather
    // registers (fire ? rc : g_*), of ik (fire ? 0 : ev_in_v ? ik + 1 : ik) and of the event pipeline (ev_k[S_PR-2] ->
    // ev_k[S_PR-1]); they are read only when iss / ev_v[S_PR-1] is set, i.e. after a fire.  Exact retiming, 0 added cycles.
    wire [12:0] g_srcl_n = fire ? rc[49:37] : g_src[12:0];
    wire [9:0]  ik_n     = fire ? 10'd0 : (ev_in_v ? ik + 10'd1 : ik);
    reg [8*13-1:0] qa_s; reg [1:0] qa_v; reg [2*13-1:0] pa_s; reg [1:0] pa_v;
    always @(posedge clk) begin : vmrq_pre
        for (integer r = 0; r < 2; r = r + 1) begin : vmrq_pre_r
            reg [10:0] i;
            i = flit_n(ik_n, r, g_r2_n);
            qa_v[r] <= fv_n(ik_n, r, g_r2_n, g_f_n) && code_n(i, g_qbg_n, g_bs_n);
            for (integer w = 0; w < 4; w = w + 1) qa_s[(r*4+w)*13 +: 13] <= g_srcl_n + 13'({i, 2'b00} + w);
            i = flit_n(ev_k[S_PR-2], r, g_r2_n);
            pa_v[r] <= fv_n(ev_k[S_PR-2], r, g_r2_n, g_f_n);
            pa_s[r*13 +: 13] <= g_srcl_n + 13'(i);
        end
    end
    // HBM-HARD-1-GQ 11-07 (vD routed slew 1303, worst 434 ps: one select flop drives 256 mux bits through 64-fanout buffers):
    // one kept copy of the bank selects and the p_d mode per 32-bit lane. Same function.
    localparam integer NLANE = 8;
    wire [NLANE*64-1:0] aq_sel_l;                      // lane L: (r*4+w)*8 + bank: one-hot bank of aq_x word (r, w)
    wire [NLANE*16-1:0] pd_sel_l;                      // lane L: r*8 + bank: one-hot bank of the p_d read word
    wire [NLANE*4-1:0]  pd_m_l;                        // lane L: r*2: p_d source 0 rdw, 1 aq_q, 2 ex_n[255:0], 3 ex_n[511:256]
    reg [127:0] ex_we;                                 // r*64 + byte: exponent byte written this edge
    reg [1:0] ex_v;                                    // r: exponent bytes written next edge (compare one stage early)
    reg ex_z;                                          // ex reads as zero (cleared by fire)
    // HBM-HARD-5 11-08 (vC routed TT -6.52/3, ECO -14.01/5: u_fcore.fire -> fire ? rc : g_* -> bank-select/mode decode ->
    // 8 lane copies, one fire flop broadcast over the core): each lane keeps its own copy of fire (same D fire_c, same
    // reset) and decodes its own selects from it, so the fire -> select path stays inside the lane.  Same function.
    for (genvar L = 0; L < NLANE; L = L + 1) begin : g_lane
        (* keep *) reg fire_k;
        always @(posedge clk or negedge rn) if (!rn) fire_k <= 1'b0; else fire_k <= fire_c;
        wire [2:0] src_l = fire_k ? rc[39:37] : g_src[2:0];
        wire       r2_l  = fire_k ? rc[1] : g_r2;
        wire       qbg_l = fire_k ? rc[0] : g_qbg;
        wire [7:0] bs_l  = fire_k ? rc[36:29] : g_bs;
        reg [63:0] aq_sel_dl; reg [15:0] pd_sel_dl; reg [3:0] pd_m_dl;
        always @* begin : nb_pre_l
            aq_sel_dl = '0; pd_sel_dl = '0; pd_m_dl = '0;
            for (integer r = 0; r < 2; r = r + 1) begin : nb_pre_r
                reg [10:0] i; reg [2:0] s;
                i = flit_n(ev_k[S_QCAP-1], r, r2_l);
                for (integer w = 0; w < 4; w = w + 1) begin
                    s = src_l + {i[0], 2'(w)};
                    aq_sel_dl[(r*4+w)*8 +: 8] = 8'd1 << s;
                end
                i = flit_n(ev_k[S_P-2], r, r2_l);
                s = src_l + i[2:0];
                pd_sel_dl[r*8 +: 8] = 8'd1 << s;
                pd_m_dl[r*2 +: 2] = !qbg_l ? 2'd0 : code_n(i, qbg_l, bs_l) ? 2'd1 : (i == {3'b0, bs_l}) ? 2'd2 : 2'd3;
            end
        end
        (* keep *) reg [63:0] aq_sel_k; (* keep *) reg [15:0] pd_sel_k; (* keep *) reg [3:0] pd_m_k;
        always @(posedge clk) begin aq_sel_k <= aq_sel_dl; pd_sel_k <= pd_sel_dl; pd_m_k <= pd_m_dl; end
        assign aq_sel_l[L*64 +: 64] = aq_sel_k; assign pd_sel_l[L*16 +: 16] = pd_sel_k; assign pd_m_l[L*4 +: 4] = pd_m_k;
    end
    // HBM-HARD-1-GQ 11-07 (vD routed TT -57 on 48 ex_we: g_r2 -> 11-bit compare -> 64 decode): compare one stage early into ex_v,
    // decode the byte index from it. As DIE-HBM-83-COLL e2310eecf1: differs from the original only for a fire with work in flight,
    // which is the sticky busy fault.
    always @(posedge clk or negedge rn)
        if (!rn) begin ex_we <= '0; ex_v <= '0; end
        else for (integer r = 0; r < 2; r = r + 1) begin : nb_pre_we
            reg [10:0] i, j;
            j = flit_n(ev_k[S_P-3], r, g_r2_n);
            ex_v[r] <= ev_v[S_P-3] && g_qbg_n && fv_n(ev_k[S_P-3], r, g_r2_n, g_f_n) && code_n(j, g_qbg_n, g_bs_n);
            i = flit_i(ev_k[S_P-2], r);
            ex_we[r*64 +: 64] <= ex_v[r] ? (64'd1 << i[5:0]) : 64'd0;
        end
    // ------------------------------------------------------------------ VM reads (issue) + response check
    reg [7:0] rd_exp; reg [7:0] rd_exp_q;
    always @(posedge clk or negedge rn) begin
        if (!rn) begin vm_rq <= '0; rd_exp <= 8'd0; rd_exp_q <= 8'd0; end
        else begin
            vm_rq <= '0;
            if (g_qbg && ev_in_v) begin
                for (integer r = 0; r < 2; r = r + 1) begin : nb_1
                    reg [15:0] s;
                    if (qa_v[r])
                        for (integer w = 0; w < 4; w = w + 1) begin
                            s = {g_src[15:13], qa_s[(r*4+w)*13 +: 13]};
                            for (integer b = 0; b < 8; b = b + 1) if (s[2:0] == 3'(b)) vm_rq[b*17 +: 17] <= {1'b1, s};
                        end
                end
            end
            if (!g_qbg && ev_v[S_PR-1]) begin
                for (integer r = 0; r < 2; r = r + 1) begin : nb_2
                    reg [15:0] s;
                    if (pa_v[r]) begin s = {g_src[15:13], pa_s[r*13 +: 13]}; for (integer b = 0; b < 8; b = b + 1) if (s[2:0] == 3'(b)) vm_rq[b*17 +: 17] <= {1'b1, s}; end
                end
            end
            // expected response valids (one edge before the capture register is loaded)
            rd_exp <= 8'd0;
            for (integer b = 0; b < 8; b = b + 1) if (vm_rq[b*17+16]) rd_exp[b] <= 1'b1;
        end
    end
    // read latency: rq register @n -> bank samples n+1 -> registered response n+7 -> pin capture n+8 (+VM_RT).
    reg [7:0] rdx [0:7+V];
    always @(posedge clk or negedge rn)
        if (!rn) for (integer d = 0; d < 8 + V; d = d + 1) rdx[d] <= 8'd0;
        else begin rdx[0] <= rd_exp; for (integer d = 1; d < 8 + V; d = d + 1) rdx[d] <= rdx[d-1]; end
    reg [2055:0] rr_q; reg [7:0] rrv_q;
    function automatic [255:0] rdw(input [2:0] b);       // captured read word of bank b (8:1 select, no runtime part-select)
        rdw = 256'd0;
        for (integer j = 0; j < 8; j = j + 1) if (b == 3'(j)) rdw = rr_q[j*257 +: 256];
    endfunction
    always @(posedge clk) rr_q <= vm_rr;
    always @(posedge clk or negedge rn)
        if (!rn) rrv_q <= 8'd0; else for (integer b = 0; b < 8; b = b + 1) rrv_q[b] <= vm_rr[b*257+256];
    // rdx[6+V] holds the expectation of the response captured in rr_q this edge
    wire rd_bad = rrv_q != rdx[6+V];
    // ------------------------------------------------------------------ quantiser feed (@9) and capture (@23)
    always @*
        if (!rn) aq_v = 2'd0;
        else for (integer r = 0; r < 2; r = r + 1) begin : nb_3
            reg [10:0] i; i = flit_i(ev_k[S_QCAP], r);
            aq_v[r] = ev_v[S_QCAP] && g_qbg && fv(ev_k[S_QCAP], r) && is_code(i);
        end
    always @* for (integer r = 0; r < 2; r = r + 1) begin : nb_4
        for (integer w = 0; w < 4; w = w + 1) begin : nb_4w
            reg [255:0] x; x = 256'd0;
            for (integer L = 0; L < NLANE; L = L + 1)
                for (integer j = 0; j < 8; j = j + 1) x[L*32 +: 32] = x[L*32 +: 32] | ({32{aq_sel_l[L*64+(r*4+w)*8+j]}} & rr_q[j*257+L*32 +: 32]);
            aq_x[r*1024 + w*256 +: 256] = x;
        end
    end
    wire [511:0] aq_q_q = {aq1_q, aq0_q}; wire [19:0] aq_e_q = {aq1_e, aq0_e};
    // ------------------------------------------------------------------ payload P (@24) + exponent words
    reg [511:0] ex;                                    // exponent words 0, 1 (bytes = e + 127)
    reg [511:0] ex_n;                                  // with this edge's blocks merged (forwarding)
    wire [9:0] kp = ev_k[S_P-1];
    always @* begin : nb_5
        ex_n = ex_z ? 512'd0 : ex;
        for (integer r = 0; r < 2; r = r + 1)
            for (integer j = 0; j < 64; j = j + 1) if (ex_we[r*64+j]) ex_n[j*8 +: 8] = 8'(aq_e_q[r*10 +: 10] + ((MUT == 2) ? 10'sd126 : 10'sd127));
    end
    reg [1:0] p_v; reg [1:0] p_tag_k; reg [9:0] p_k; reg [255:0] p_d [0:1]; reg [10:0] p_i [0:1];
    always @(posedge clk or negedge rn)
        if (!rn) p_v <= 2'd0;
        else for (integer r = 0; r < 2; r = r + 1) p_v[r] <= ev_v[S_P-1] && fv(kp, r);
    always @(posedge clk) begin
        ex <= ex_n; ex_z <= fire;
        p_k <= kp;
        for (integer r = 0; r < 2; r = r + 1) begin : nb_7
            reg [10:0] i; reg [255:0] x, y; i = flit_i(kp, r); p_i[r] <= i;
            x = 256'd0;
            for (integer L = 0; L < NLANE; L = L + 1) begin
                for (integer j = 0; j < 8; j = j + 1) x[L*32 +: 32] = x[L*32 +: 32] | ({32{pd_sel_l[L*16+r*8+j]}} & rr_q[j*257+L*32 +: 32]);
                case (pd_m_l[L*4+r*2 +: 2])
                    2'd0: y[L*32 +: 32] = x[L*32 +: 32];
                    2'd1: y[L*32 +: 32] = aq_q_q[r*256+L*32 +: 32];
                    2'd2: y[L*32 +: 32] = ex_n[L*32 +: 32];
                    default: y[L*32 +: 32] = ex_n[256+L*32 +: 32];
                endcase
            end
            p_d[r] <= y;
        end
    end
    // ------------------------------------------------------------------ ring B commands (lp @24, read @25, inject @27, rx @27+2h)
    // and ring-A gather commands (same edges into A1, merge register one edge later)
    reg [290:0] cb [0:1];      // per ring: {lp_we, lp_tag, lp_data, rd, rd_tag, inj2, fwd2, tag3, ttl4, rx2, kind4, src4, rtag6}
    always @* begin : nb_8
        for (integer r = 0; r < 2; r = r + 1) begin : nb_9
            reg lpw; reg [2:0] lpt; reg [255:0] lpd; reg rd; reg [2:0] rdt; reg [1:0] inj, fwd, rx; reg [2:0] ttg;
            reg [3:0] ttl, kind, src; reg [5:0] rtag; reg [9:0] k;
            lpw = 0; lpt = 0; lpd = 0; rd = 0; rdt = 0; inj = 0; fwd = 0; rx = 0; ttg = 0; ttl = 0; kind = 0; src = 0; rtag = 0;
            // lp write of the payload: computed with P (ev[23]); P itself is the data
            k = ev_k[S_BLP-1];
            if (ev_v[S_BLP-1] && fv(k, r)) begin lpw = 1; lpt = k[2:0]; end
            k = ev_k[S_BRD-1];
            if (ev_v[S_BRD-1] && fv(k, r)) begin rd = 1; rdt = k[2:0]; end
            k = ev_k[S_BINJ-1];
            if (ev_v[S_BINJ-1] && fv(k, r)) begin inj[k[0]] = 1; ttg = k[2:0]; ttl[k[0]*2 +: 2] = 2'd3; end
            for (integer h = 1; h <= 3; h = h + 1) begin
                k = ev_k[S_BRX + 2*h - 1];
                if (ev_v[S_BRX + 2*h - 1] && fv(k, r)) begin
                    rx[k[0]] = 1; kind[k[0]*2 +: 2] = 2'd3; src[k[0]*2 +: 2] = srcq(q_id, k[0], h); rtag[k[0]*3 +: 3] = k[2:0];
                    if (h < 3) fwd[k[0]] = 1;
                end
            end
            cb[r] = {lpw, lpt, 256'd0, rd, rdt, inj, fwd, ttg, ttl, rx, kind, src, rtag};
        end
    end
    // P is loaded on the lp edge, so the lp data of the registered command word is P (r).
    reg [290:0] a1;             // ring-A gather command (ring B timing)
    reg [290:0] b1;             // ring B command register (MUT 5: one more edge)
    always @(posedge clk or negedge rn)
        if (!rn) begin a1 <= '0; b1 <= '0; end
        else begin a1 <= cb[0]; b1 <= cb[1]; end
    wire [255:0] a1_d = p_d[0], b1_d = p_d[1];
    assign ld_ev_v = ev_v[V]; assign ld_ev_k = ev_k[V]; assign ld_p_v = p_v; assign ld_p_d = {p_d[1], p_d[0]};
    reg [290:0] b2; reg [255:0] b2_d;
    always @(posedge clk or negedge rn) if (!rn) b2 <= '0; else b2 <= b1;
    always @(posedge clk) b2_d <= b1_d;
    wire [290:0] bo = (MUT == 5) ? b2 : b1;
    wire [255:0] bo_d = (MUT == 5) ? b2_d : b1_d;
    always @* begin : nb_10
        {rb_lp_we, rb_lp_tag} = bo[290:287]; rb_lp_data = bo_d;
        {rb_state_read_tx, rb_state_tx_tag, rb_tx_inject, rb_tx_forward, rb_tx_tag, rb_tx_ttl, rb_rx_slot, rb_rx_kind,
         rb_rx_src, rb_rx_tag} = bo[30:0];
    end
    // ------------------------------------------------------------------ ring-A merge register (ISA +2 edges)
    reg [57:0] isa_q; reg [255:0] isa_d_q;
    always @(posedge clk or negedge rn) if (!rn) isa_q <= '0; else isa_q <= isa_ring;
    always @(posedge clk) isa_d_q <= isa_lp_data;
    reg merge_bad;
    always @(posedge clk or negedge rn) begin
        if (!rn) begin
            {ra_lp_we, ra_state_read_add, ra_state_read_tx, ra_state_read_rr, ra_add_v, ra_tx_inject, ra_tx_forward,
             ra_tx_gather, ra_rx_slot, ra_rr_local} <= '0;
            merge_bad <= 1'b0;
        end else begin
            ra_lp_we <= isa_q[0] | a1[290];
            ra_state_read_add <= isa_q[4];
            ra_state_read_tx <= isa_q[11] | a1[30];
            ra_state_read_rr <= isa_q[16];
            ra_add_v <= isa_q[20];
            ra_tx_inject <= isa_q[28:27] | a1[26:25];
            ra_tx_forward <= isa_q[30:29] | a1[24:23];
            ra_tx_gather <= |a1[26:25];
            ra_rx_slot <= isa_q[39:38] | a1[15:14];
            ra_rr_local <= isa_q[54];
            merge_bad <= (isa_q[0] && a1[290]) || (isa_q[11] && a1[30]) || |(isa_q[28:27] & a1[26:25]) ||
                         |(isa_q[30:29] & a1[24:23]) || |(isa_q[39:38] & a1[15:14]) ||
                         (|a1[26:25] && |isa_q[28:27]);
        end
    end
    always @(posedge clk) begin
        ra_lp_tag <= isa_q[3:1] | a1[289:287];
        ra_lp_data <= a1[290] ? a1_d : isa_d_q;
        ra_state_add_tag <= isa_q[7:5]; ra_state_add_src <= isa_q[9:8]; ra_state_add_rhs_acc <= isa_q[10];
        ra_state_tx_tag <= isa_q[14:12] | a1[29:27]; ra_state_tx_acc <= isa_q[15];
        ra_state_rr_tag <= isa_q[19:17];
        ra_add_tag <= isa_q[23:21]; ra_add_src <= isa_q[25:24]; ra_add_rhs_acc <= isa_q[26];
        ra_tx_tag <= isa_q[33:31] | a1[22:20]; ra_tx_dst <= isa_q[35:34]; ra_tx_result <= isa_q[36]; ra_tx_acc <= isa_q[37];
        ra_tx_ttl <= a1[19:16];
        ra_rx_kind <= isa_q[43:40] | a1[13:10]; ra_rx_src <= isa_q[47:44] | a1[9:6]; ra_rx_tag <= isa_q[53:48] | a1[5:0];
        ra_rr_local_tag <= isa_q[57:55];
    end
    always @(posedge clk or negedge rn)
        if (!rn) flt_q <= 1'b0; else flt_q <= rd_bad || merge_bad;
endmodule

// Landing leaf: captures both rings' publishes and the local payload P, and writes the quadrant VM through the COLL
// kq port (via the kq share). Every input pin-registered, every output a register. Stages as the issue leaf's.
`default_nettype wire
